from manim import *

class LinkedListScene(Scene):
    def construct(self):
        # Create 3 nodes
        nodes = VGroup(*[
            VGroup(
                Square(side_length=1, color=BLUE, fill_opacity=0.3),
                Text(str(val), font_size=36)
            ) for val in [10, 20, 30]
        ]).arrange(RIGHT, buff=1.5)

        # Create arrows
        arrows = VGroup(*[
            Arrow(nodes[i].get_right(), nodes[i+1].get_left(), buff=0.1, color=YELLOW)
            for i in range(len(nodes)-1)
        ])

        self.play(LaggedStart(*[Create(node) for node in nodes], lag_ratio=0.5))
        self.play(Create(arrows))
        self.wait(2)
